window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-06b4142720f90757"]={"versions": [{"id": "FIG-06b4142720f90757", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockschaltbild der AUTOSAR-Classic-Platform-Basissoftware (BSW-Schichtenarchitektur). Dargestellt ist die Einbettung des XCP-Moduls in die BSW-Schichten (Communication Services / System Services) oberhalb der Hardware-Abstraktionsschicht sowie dessen Einordnung parallel zum klassischen AUTOSAR-Kommunikationsstack (COM, DCM, IPDUM, PDU-Router).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Schichten (von oben nach unten):\n<ul class=\"fig-list\"><li>Runtime Environment (<code>RTE</code>, orange).\n</li><li>Services Layer (blau) mit zwei Hauptbereichen:\n<ul class=\"fig-list\"><li>Flankierend: Betriebssystem (<code>OS</code>), horizontal gekoppelt mit dem XCP-Protokoll.\n</li><li>XCP-Modul (dick umrandet): Bestehend aus dem Protokollkern <code>XCP Protocol</code> und den drei busspezifischen Transportschichten <code>XCPonCan</code>, <code>XCPonFr</code> sowie <code>XCPonEth</code>.\n</li><li>Standard-Kommunikationsstack: <code>IPDUM</code>, <code>COM</code>, <code>DCM</code> (oben), zentraler <code>PDUR</code> (PDU Router) sowie darunter Transportprotokoll (<code>TP</code>) und Netzwerkmanagement (<code>NM</code>).\n</li></ul>\n</li><li>Communication HW Abstraction (grün) mit <code>Bus Interfac(s)</code>.\n</li><li>Communication Drivers (rot) mit <code>Bus Driver(s)</code>.\n</li></ul>\n</li><li>Schnittstellen und Pfade:\n<ul class=\"fig-list\"><li>Schwarze Doppelpfeile (Datenpfad / Signale &amp; PDUs): Bidirektionale Verbindungen zwischen RTE &lt;-&gt; COM; COM, IPDUM, DCM &lt;-&gt; PDUR; PDUR &lt;-&gt; TP, NM; PDUR, TP, NM &lt;-&gt; Bus Interfac(s); XCPonCan, XCPonFr, XCPonEth &lt;-&gt; Bus Interfac(s); Bus Interfac(s) &lt;-&gt; Bus Driver(s).\n</li><li>Orange Doppelpfeile (Kontrollpfad): Verbindung zwischen OS &lt;-&gt; XCP Protocol sowie zwischen XCPonFr &lt;-&gt; Bus Interfac(s) (FlexRay Interface).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Datenpfad (schwarze Pfeile):\n<ul class=\"fig-list\"><li>Kalibrier- und Messdaten (XCP-PDUs) werden im XCP-Modul über <code>XCPonCan</code>, <code>XCPonFr</code> oder <code>XCPonEth</code> direkt an die jeweiligen <code>Bus Interfac(s)</code> übergeben, unter Umgehung des AUTOSAR PDU-Routers (<code>PDUR</code>).\n</li><li>Reguläre Anwendungs- und Diagnosedaten fließen separat über RTE, COM, DCM und PDUR an TP bzw. direkt an die Bus Interfaces.\n</li></ul>\n</li><li>Kontrollpfad (orange Pfeile):\n<ul class=\"fig-list\"><li>Das Betriebssystem (<code>OS</code>) steuert und synchronisiert das <code>XCP Protocol</code> (Triggerung von Tasks, DAQ-Listen und Ereignissen).\n</li><li><code>XCPonFr</code> steuert über den Kontrollpfad das FlexRay Interface direkt (z. B. Puffer- und Slot-Zuweisung, Synchronisation auf den FlexRay-Zyklus).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Anforderungen:\n<ul class=\"fig-list\"><li>[SWS_Xcp_00701]: Das AUTOSAR XCP-Modul muss bei CAN und FlexRay oberhalb der busspezifischen Schnittstellen angeordnet sein. Bei Ethernet fordert die Spezifikation die Anordnung oberhalb des Socket Adaptors (<code>SoAd</code>).\n</li><li>[SWS_Xcp_00702]: Verortung der Busschnittstellen in der Abstraktionsschicht.\n</li></ul>\n</li><li>Architektur-Inkonsistenz im Diagramm: Obwohl [SWS_Xcp_00701] explizit <code>SoAd</code> für Ethernet nennt, ist im vorliegenden Schaubild (R4.1.3) kein <code>SoAd</code> dargestellt; <code>XCPonEth</code> bindet grafisch direkt an <code>Bus Interfac(s)</code> an.\n</li><li>Entwickler-Hinweis: Für FlexRay ist zwingend die Doppelverbindung aus Datenpfad und Kontrollpfad zum FlexRay Interface zu implementieren.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c7690a42d9a302a7", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockschaltbild der AUTOSAR-Classic-Platform-Basissoftware (BSW-Schichtenarchitektur). Dargestellt ist die Einbettung des XCP-Moduls in die BSW-Schichten (Communication Services / System Services) oberhalb der Hardware-Abstraktionsschicht sowie dessen Einordnung parallel zum klassischen AUTOSAR-Kommunikationsstack (COM, DCM, IPDUM, PDU-Router).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Schichten (von oben nach unten):\n<ul class=\"fig-list\"><li>Runtime Environment (<code>RTE</code>, orange).\n</li><li>Services Layer (blau):\n<ul class=\"fig-list\"><li>Flankierend: <code>OS</code> mit oranger Kontrollpfad-Anbindung an <code>XCP Protocol</code>.\n</li><li>XCP-Modul (dick umrandet): Der obere Bereich <code>XCP Protocol</code> ist in der Höhe reduziert. Darunter befinden sich die vertikal verlängerten Blöcke <code>XCPonCan</code> und <code>XCPonFr</code> sowie eine zweigeteilte Ethernet-Spalte: oben <code>SoAd</code> (Socket Adaptor), darunter <code>XCPonEth</code>.\n</li><li>Standard-Kommunikationsstack: <code>IPDUM</code>, <code>COM</code>, <code>DCM</code>, <code>PDUR</code>, <code>TP</code>, <code>NM</code>.\n</li></ul>\n</li><li>Communication HW Abstraction (grün) mit <code>Bus Interfac(s)</code>.\n</li><li>Communication Drivers (rot) mit <code>Bus Driver(s)</code>.\n</li></ul>\n</li><li>Schnittstellen und Pfade:\n<ul class=\"fig-list\"><li>Schwarze Doppelpfeile (Datenpfad): XCPonCan, XCPonFr und XCPonEth verbinden weiterhin nach unten zu <code>Bus Interfac(s)</code>. Zwischen DCM und PDUR ist der Verbindungsvektor an die linke Kante verschoben und weist einen Darstellungsfehler auf (horizontale Spitzen nach rechts statt vertikal bidirektional).\n</li><li>Orange Doppelpfeile (Kontrollpfad): Unverändert zwischen OS &lt;-&gt; XCP Protocol sowie XCPonFr &lt;-&gt; Bus Interfac(s).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Datenpfad (schwarze Pfeile):\n<ul class=\"fig-list\"><li>XCP-PDUs über CAN und FlexRay laufen wie bisher von <code>XCPonCan</code> und <code>XCPonFr</code> direkt in die <code>Bus Interfac(s)</code>.\n</li><li>Der Ethernet-Übertragungsweg bindet nun visuell den Socket Adaptor (<code>SoAd</code>) innerhalb des XCP-Blocks ein (oberhalb von <code>XCPonEth</code>), während die Kopplung zu den <code>Bus Interfac(s)</code> weiterhin von <code>XCPonEth</code> ausgeht.\n</li><li>Standard-Kommunikationsdaten laufen unverändert über RTE, COM, DCM und PDUR.\n</li></ul>\n</li><li>Kontrollpfad (orange Pfeile):\n<ul class=\"fig-list\"><li>Unveränderte Ereignis- und Zyklustriggerung des XCP-Protokolls durch das OS.\n</li><li>Direkte Steuerungsinteraktion von <code>XCPonFr</code> mit dem FlexRay Interface.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Relevanz:\n<ul class=\"fig-list\"><li>Umsetzung von [SWS_Xcp_00701]: <code>SoAd</code> wurde im Diagramm ergänzt, um der Anforderung („In case of Ethernet, the AUTOSAR XCP module shall be located above the Socket Adaptor“) Rechnung zu tragen.\n</li></ul>\n</li><li>Spezifikations- und Darstellungsfehler:\n<ul class=\"fig-list\"><li>Verkehrte Schichtung im Diagramm: Visuell liegt <code>SoAd</code> innerhalb des XCP-Moduls oberhalb von <code>XCPonEth</code>, und <code>XCPonEth</code> dockt an <code>Bus Interfac(s)</code> an. Nach der normativen AUTOSAR-Architektur muss <code>XCPonEth</code> das XCP-Modul nach unten abschließen und auf <code>SoAd</code> aufsetzen, welcher wiederum auf <code>TcpIp</code> / <code>EthIf</code> aufbaut.\n</li><li>Zeichnungsfehler bei DCM-Anbindung: Der Pfeil zwischen DCM und PDUR ist an die Blockkante verschoben und besitzt horizontal nach rechts zeigende Spitzen; implementierungsseitig bleibt die Schnittstelle ein standardmäßiger vertikaler, bidirektionaler PDU-Austausch.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-06b4142720f90757", "to": "FIG-c7690a42d9a302a7", "fr": "R4.1.3", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>XCP-Modul (Ethernet-Zweig)</code>: Aufnahme des Moduls <code>SoAd</code> (Socket Adaptor) in die rechte Spalte oberhalb von <code>XCPonEth</code> bei gleichzeitiger Verringerung der Höhe des Blocks <code>XCP Protocol</code> und Anhebung der horizontalen Trennlinie.\n</li><li><code>DCM / PDUR</code>: Verbindungsvektor an die linke Kante von DCM verschoben und zeichnerisch fehlerhaft mit zwei nach rechts weisenden Pfeilspitzen dargestellt.\n</li></ul>"}]};
